    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_paste_bridge_core_fn_free_apiserver(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_paste_bridge_core_fn_clone_apiserver(handle, status)
        }
    }

    override fun `port`(): kotlin.UShort {
            return FfiConverterUShort.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_paste_bridge_core_fn_method_apiserver_port(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * 移动端 (Android/iOS) 用的入口: 通过 UniFFI callback interface 拿到
     * 历史 / 剪贴板推送 / 窗口可见性,不再依赖 `Arc<AppState>` 这种
     * FFI 不好导出的 Rust 内部类型。
     */
    @Throws(PasteBridgeException::class)override fun `startWithCallbacks`(`callbacks`: ClipboardApiCallback)
        = 
    callWithHandle {
    uniffiRustCallWithError(PasteBridgeException) { _status ->
    UniffiLib.uniffi_paste_bridge_core_fn_method_apiserver_start_with_callbacks(
        it,
        FfiConverterTypeClipboardApiCallback.lower(`callbacks`),_status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeApiServer: FfiConverter<ApiServer, Long> {
    override fun lower(value: ApiServer): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): ApiServer {
        return ApiServer(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): ApiServer {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ApiServer) = 8UL

    override fun write(value: ApiServer, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


