    , 
    /**
     * 设备提供的 PasteBridge HTTP API 端口
     */
    var `port`: kotlin.UShort
    , 
    /**
     * mDNS 完整服务名，便于去重
     */
    var `fullname`: kotlin.String
    
){
    

    

    
    companion object
}

