    }
}



/**
 * 单次 sync 结果,用于驱动 UI 反馈 (toast / 状态条 / 计数)。
 */
data class SyncReport (
    /**
     * 这次 sync 的对端 device_id。
     */
    var `peerDeviceId`: kotlin.String
    , 
    /**
     * 拉到了多少条 (去重前)。
     */
    var `pulledTotal`: kotlin.ULong
    , 
    /**
     * 实际新增了多少条 (按 `content_hash` 去重后)。
     */
    var `pulledAdded`: kotlin.ULong
    , 
    /**
     * 推了几条 (0 = 本地没有文本,或本端最新文本 hash 已存在于对端)。
     */
    var `pushed`: kotlin.ULong
    , 
    /**
     * 任意一方向失败时的错误描述, 没出错时为 None。
     */
    var `error`: kotlin.String?
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSyncReport: FfiConverterRustBuffer<SyncReport> {
    override fun read(buf: ByteBuffer): SyncReport {
        return SyncReport(
            FfiConverterString.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: SyncReport) = (
            FfiConverterString.allocationSize(value.`peerDeviceId`) +
            FfiConverterULong.allocationSize(value.`pulledTotal`) +
            FfiConverterULong.allocationSize(value.`pulledAdded`) +
            FfiConverterULong.allocationSize(value.`pushed`) +
            FfiConverterOptionalString.allocationSize(value.`error`)
    )

    override fun write(value: SyncReport, buf: ByteBuffer) {
            FfiConverterString.write(value.`peerDeviceId`, buf)
            FfiConverterULong.write(value.`pulledTotal`, buf)
            FfiConverterULong.write(value.`pulledAdded`, buf)
            FfiConverterULong.write(value.`pushed`, buf)
            FfiConverterOptionalString.write(value.`error`, buf)
    }
}





/**
 * 跨平台错误类型。UniFFI 要求 `Result<_, _>` 的 Err 必须是
 * `#[derive(uniffi::Error)]` 标注的具体 enum/class,不能用裸 `String`。
 */
sealed class PasteBridgeException: kotlin.Exception() {
    
    /**
     * 通用错误,消息直接给移动端 toast。
     */
    class Generic(
        
        val `message`: kotlin.String
        ) : PasteBridgeException() {
        override val message
            get() = "message=${ `message` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PasteBridgeException> {
        override fun lift(error_buf: RustBuffer.ByValue): PasteBridgeException = FfiConverterTypePasteBridgeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePasteBridgeError : FfiConverterRustBuffer<PasteBridgeException> {
    override fun read(buf: ByteBuffer): PasteBridgeException {
        

        return when(buf.getInt()) {
            1 -> PasteBridgeException.Generic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PasteBridgeException): ULong {
        return when(value) {
            is PasteBridgeException.Generic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: PasteBridgeException, buf: ByteBuffer) {
        when(value) {
            is PasteBridgeException.Generic -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





